item.content:encoded:
/*======================
 *  background image/colours
 * ===================*/

/* large screen format */
@media only screen and (min-width: 1600px) {
body {
  background: linear-gradient(0deg, rgba(227,232,242,0.99) 0%, rgba(236,249,252,0.5) 45%, rgba(240,249,252,0.3) 63%)  no-repeat fixed, url("/wp-content/uploads/sites/1240/2021/07/MO_header_full_transparancy_bottom@2x-2.png") no-repeat fixed bottom !important;
	background-color: #FFF!important;
	  background-size: contain !important;
}
}

/* medium screen format */
@media (min-width: 950px) and (max-width: 1600px) {
body {
  background: linear-gradient(0deg, rgba(227,232,242,0.99) 0%, rgba(236,249,252,0.5) 45%, rgba(240,249,252,0.6) 63%)  no-repeat fixed, url("/wp-content/uploads/sites/1240/2021/07/MO_header_full_transparancy_bottom@2x-2.png") no-repeat bottom   !important;
	background-color: #FFF!important;
	  background-size: contain !important;
}
}

/* mobile/tablet format */
@media only screen and (max-width: 950px) {
body {
  background: linear-gradient(0deg, rgba(227,232,242,0.99) 0%, rgba(236,249,252,0.5) 45%, rgba(240,249,252,0.6) 63%)  no-repeat fixed, url("/wp-content/uploads/sites/1240/2021/07/MO_header_full_transparancy_mobile_top@2x.png") no-repeat top, url("/wp-content/uploads/sites/1240/2021/07/MO_header_full_transparancy_bottom@2x-2.png") no-repeat bottom   !important;
	background-color: #FFF!important;
	  background-size: contain !important;
}
}

/* Adding menu gradient and blur */
.kad-fixed-vertical-background-area {
		background: linear-gradient(0deg, rgba(227,227,238,0.8) 0%, rgba(236,249,252,0.5) 33%, rgba(240,249,252,0.7) 63%)!important;
	 backdrop-filter: blur(5px) saturate(1.2);
			backdrop-filter: blur(5px) saturate(1.2);
		filter: drop-shadow(0.2rem 0.2em 0.6rem rgba(211,226,241,0.7203256302521008));
}

/* add padding to menu logo */
.kad-vertical-menu .logocase {
	padding: 50px 10px 40px;
}


/* remove uppercase on menu */
.menu-item a {
	text-transform: unset !important;
}


/* adjust menu arrow */
.kt-show-vertsub-indicator .sf-vertical .sf-dropdown-submenu>a:after, .kt-show-vertsub-indicator .sf-vertical .sf-dropdown>a:after {
	color: #44388c;
	right: 2em;
}

/* removing unhovered white line on links */
.comment-content a:not(.button), .entry-content p a:not(.button):not(.select2-choice):not([data-rel=lightbox]) {
	border-bottom: 2px solid rgba(255, 255, 255, 0);
}

/* removing extra line on acknowledgements footer */
.footerclass .footer-widget-title:before {
	display: none;
}

/* padding above footer*/
#containerfooter {
	padding-top: 50px;
}

/* homepage header styling */
/* 	.page-header {
	border-bottom: 3px solid rgba(227,232,242,0.99);
	margin-top: 50px;
		background: radial-gradient(circle, rgba(245,250,255,0.2) 0%, rgba(222,226,241,0.2) 68%, rgba(212,204,224,0.1) 100%) !important;
		backdrop-filter: blur(5px) saturate(1.2);
		filter: drop-shadow(0 0 0.75rem #d3e2f1); 
} */


/* removing extra padding above content area */
.container .container-contained {
	padding-top: 0px !important;
}

/* padding above bottom post navigation area */
.entry-content {
	padding-bottom: 30px !important;
}

/* Mobile menu colour */
.kt-mobile-menu {
	background-color: #44388c !important;
}

/* Remove extra homepage padding for image menu */
.home-padding {
	padding: 0;
}

/* Add padding to Ackwnoledgements */
#text-6 {
	padding: 0 0 20px 40px;
}

/*======================
 *  stylings for page items
 * ===================*/

/* glass id for noteboxes */
#glass {
		background: radial-gradient(circle, rgba(245,250,255,0.4) 0%, rgba(222,226,241,0.4) 68%, rgba(212,204,224,0.2) 100%) !important;
		backdrop-filter: blur(5px) saturate(1.2);
		filter: drop-shadow(0 0 0.75rem #d3e2f1);
}

/* glass on profile boxes */
.kt-blocks-info-box-link-wrap {
		background: radial-gradient(circle, rgba(245,250,255,0.4) 0%, rgba(222,226,241,0.4) 68%, rgba(212,204,224,0.2) 100%) !important;
		backdrop-filter: blur(5px) saturate(1.2);
		filter: drop-shadow(0.5rem 0.5em 0.75rem #d3e2f1);
}

/* Glass look on kadence accordions */
.kt-blocks-accordion-header {
		background: radial-gradient(circle, rgba(245,250,255,0.7) 0%, rgba(222,226,241,0.4) 68%, rgba(212,204,224,0.2) 100%) !important;
		backdrop-filter: blur(5px) saturate(1.2);
		filter: drop-shadow(0 0 0.75rem #d3e2f1);
}
/* activie accordion colour */
.kt-accordion-panel-active {
	border-color: #9caad2 !important;
}

/* center videos */
.wp-block-embed {
    width: 70%;
    margin: auto;
		margin-top: 30px;
		margin-bottom: 30px;
    display:block;
}

/* list styling */
ol, ul {
	margin-bottom: 30px;
  margin-left: 30px;
}

/* force image center */
img {
	display: block;
  margin-left: auto;
  margin-right: auto;
}

/* remove line border on homepage navigation blocks */
.image_menu_item_link .image_menu_message {
	border: 0px;
}
